sub is_perfect {
    my ($n) = @_;
    return 0 if $n < 2;
    my $sum = 1;  # 1 دائمًا قاسم
    # البحث عن القواسم حتى الجذر التربيعي
    for my $i (2 .. int(sqrt($n))) {
        if ($n % $i == 0) {
            $sum += $i;
            $sum += $n / $i if $i != $n / $i;
        }
    }
    return $sum == $n;
}

