# طابور أولوية: نُبقي المصفوفة مرتبة تنازلياً حسب الأولوية
my @pq;

sub enqueue {
    my ($item, $priority) = @_;
    my $pos = 0;
    # نجد موضع الإدراج: نبحث عن أول عنصر بأولوية أقل
    $pos++ while $pos < @pq && $pq[$pos][1] >= $priority;
    splice @pq, $pos, 0, [$item, $priority];
}

sub dequeue {
    return shift @pq;  # الأعلى أولوية في البداية
}

