use strict;
use warnings;

sub quick_sort {
    my @arr = @_;
    return @arr if @arr < 2;

    my $pivot = $arr[0];
    my @less;
    my @greater;

    foreach my $i (1 .. $#arr) {
        if ($arr[$i] <= $pivot) {
            push @less, $arr[$i];
        } else {
            push @greater, $arr[$i];
        }
    }

    return (quick_sort(@less), $pivot, quick_sort(@greater));
}

