for my $ch (split //, $input) {
    push @stack, $ch;
}

my $reversed = '';
# فرقعة حتى يفرغ المكدّس
while (@stack) {
    $reversed .= pop @stack;
}

print "$reversed\n";

use strict;
use warnings;
use List::Util qw(sum);

my @data = (5, 3, 9, 1, 7, 7, 2);

# ترتيب البيانات لحساب الوسيط
my @sorted = sort { $a <=> $b } @data;
my $n = scalar @sorted;
my $median;
if ($n % 2) {
    $median = $sorted[int($n/2)];
} else {
    $median = ($sorted[$n/2 - 1] + $sorted[$n/2]) / 2;
}

my $mean = sum(@data) / $n;

# حساب التباين ثم الانحراف المعياري
my $variance = sum(map { ($_ - $mean) ** 2 } @data) / $n;
my $stddev = sqrt($variance);

printf "Mean: %.2f\n", $mean;
printf "Median: %.2f\n", $median;
printf "StdDev: %.2f\n", $stddev;

