use strict;
use warnings;

sub hanoi {
    my ($n, $from, $to, $aux) = @_;
    if ($n == 1) {
        print "Move disk 1 from $from to $to\n";
        return;
    }
    hanoi($n - 1, $from, $aux, $to);
    print "Move disk $n from $from to $to\n";
    hanoi($n - 1, $aux, $to, $from);
}

# ثلاثةُ أقراصٍ فقط لنتيجةٍ قصيرة
hanoi(3, 'A', 'C', 'B');

