use strict;
use warnings;

# نقرأ سطراً من STDIN ونزيل السطر الجديد
while (my $line = <STDIN>) {
    chomp $line;
    # نتوقف عند سطر فارغ
    last if $line eq '';
    # نطبع طول السطر
    print length($line), "\n";
}

